    /* === NAVIGATION (for conversion tooling) ===
       The html_to_pptx.py script navigates via ArrowRight.
       We implement snap-to-slide navigation so each keypress
       reliably advances to the next full-screen slide. */
    (function(){
      const slides = Array.from(document.querySelectorAll('[data-slide], .slide'));
      let idx = 0;

      function go(i){
        idx = Math.max(0, Math.min(slides.length - 1, i));
        slides[idx].scrollIntoView({ behavior: 'instant', block: 'start' });
      }

      // Keep idx in sync if user scrolls
      const io = new IntersectionObserver((entries)=>{
        for(const e of entries){
          if(e.isIntersecting){
            const i = slides.indexOf(e.target);
            if(i >= 0) idx = i;
          }
        }
      }, { threshold: 0.55 });
      slides.forEach(s=>io.observe(s));

      window.addEventListener('keydown', (e)=>{
        if(e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' '){
          e.preventDefault(); go(idx + 1);
        }
        if(e.key === 'ArrowLeft' || e.key === 'PageUp'){
          e.preventDefault(); go(idx - 1);
        }
        if(e.key === 'Home'){ e.preventDefault(); go(0); }
        if(e.key === 'End'){ e.preventDefault(); go(slides.length - 1); }
      }, { passive: false });

      // Ensure we start at slide 1
      window.addEventListener('load', ()=>{ go(0); });
    })();
  </script>
