      width: 70%; height: 70%;
      transform: rotate(-18deg);
      background: linear-gradient(90deg, rgba(51,227,176,0), rgba(51,227,176,.22), rgba(255,94,168,.20), rgba(255,94,168,0));
      opacity:.95;
    }

    /* === CHARTS === */
    .chart-wrap{margin-top: clamp(16px, 2.8vw, 30px);}

    .barlist{display:flex; flex-direction:column; gap: clamp(10px, 1.5vw, 14px);}
    .barrow{
      display:grid;
      grid-template-columns: minmax(180px, 28%) 1fr minmax(88px, 12%);
      gap: clamp(10px, 1.6vw, 16px);
      align-items:center;
    }
    .barlabel{
      font-size: clamp(12px, 1.55vw, 18px);
      color: rgba(234,241,255,.86);
      font-weight: 600;
      line-height: 1.15;
    }
    .bartrack{
      height: clamp(10px, 1.5vw, 16px);
      border-radius: 999px;
      background: rgba(234,241,255,.10);
      overflow:hidden;
      position:relative;
    }
    .barfill{
      height: 100%;
      width: calc(var(--pct) * 1%);
      background: linear-gradient(90deg, rgba(51,227,176,.95), rgba(120,166,255,.85));
      border-radius: 999px;
    }
    .barvalue{
      font-family: var(--mono);
      font-size: clamp(11px, 1.25vw, 14px);
      color: rgba(234,241,255,.70);
      text-align:right;
    }

    /* === PAIRED BARS === */
    .pair{
      margin-top: clamp(14px, 2.4vw, 26px);
      display:grid;
      grid-template-columns: 1fr 1fr;
      gap: clamp(14px, 2.6vw, 28px);
      align-items: stretch;
    }
    .paircard{
      border: 1px solid rgba(234,241,255,.14);
      border-radius: clamp(16px, 2.0vw, 22px);
      background: rgba(255,255,255,.03);
      padding: clamp(16px, 2.6vw, 24px);
      overflow:hidden;
      position:relative;
    }
    .pairname{font-size: clamp(14px, 1.6vw, 18px); color: rgba(234,241,255,.86); font-weight: 700;}
    .pairnum{font-family: var(--serif); font-weight: 700; font-size: clamp(34px, 4.6vw, 64px); margin-top: clamp(6px, 1.0vw, 10px);}
    .pairbar{margin-top: clamp(12px, 1.8vw, 16px); height: clamp(12px, 1.8vw, 18px); border-radius: 999px; background: rgba(234,241,255,.10); overflow:hidden;}
    .pairbar > div{height:100%; width: calc(var(--pct) * 1%); border-radius:999px; background: linear-gradient(90deg, rgba(255,94,168,.92), rgba(51,227,176,.92));}
    .parity{
      margin-top: clamp(14px, 2.4vw, 22px);
      display:flex; gap: clamp(10px, 1.6vw, 16px);
      align-items:center;
      padding: clamp(10px, 1.6vw, 14px) clamp(12px, 2.0vw, 16px);
      border-radius: 999px;
      border: 1px solid rgba(234,241,255,.14);
      background: rgba(255,255,255,.03);
      width: fit-content;
      color: rgba(234,241,255,.78);
      font-size: clamp(12px, 1.35vw, 16px);
    }
    .parity strong{color: var(--fg)}

    /* === SEVERITY VISUALS === */
    .compare{
      margin-top: clamp(16px, 2.6vw, 26px);
      display:grid;
      grid-template-columns: 1.25fr .9fr;
      gap: clamp(14px, 2.6vw, 28px);
      align-items: start;
    }
    .mini{
      border:1px solid rgba(234,241,255,.14);
      background: rgba(255,255,255,.03);
      border-radius: clamp(16px, 2.0vw, 22px);
      padding: clamp(14px, 2.2vw, 18px);
    }
    .stack{
      display:flex; flex-direction:column; gap: clamp(10px, 1.4vw, 14px);
      margin-top: clamp(8px, 1.4vw, 12px);
    }
    .stackbar{height: clamp(12px, 1.8vw, 18px); border-radius: 999px; background: rgba(234,241,255,.10); overflow:hidden;}
    .stackbar > div{height:100%; width: calc(var(--pct) * 1%); border-radius:999px; background: linear-gradient(90deg, rgba(120,166,255,.92), rgba(51,227,176,.92));}

    /* === ICON/INFOGRAPHIC GRID === */
    .icon-grid{margin-top: clamp(16px, 2.8vw, 28px); display:grid; grid-template-columns: repeat(4, 1fr); gap: clamp(10px, 1.8vw, 16px);}
    .icon-card{border:1px solid rgba(234,241,255,.14); background: rgba(255,255,255,.03); border-radius: clamp(16px, 2.0vw, 22px); padding: clamp(12px, 2.2vw, 16px);}
    .icon{width: clamp(34px, 4.0vw, 52px); height: clamp(34px, 4.0vw, 52px); border-radius: 14px; display:grid; place-items:center; background: rgba(51,227,176,.16); border:1px solid rgba(51,227,176,.26);}
    .icon svg{width:70%; height:70%;}
    .icon-title{margin-top: clamp(10px, 1.4vw, 12px); font-weight:700; color: rgba(234,241,255,.86); font-size: clamp(12px, 1.45vw, 16px);}
    .icon-text{margin-top: clamp(6px, .9vw, 10px); color: rgba(234,241,255,.64); font-size: clamp(11px, 1.25vw, 14px); line-height: 1.35;}

    /* === COPING GRID === */
    .coping{margin-top: clamp(16px, 2.8vw, 28px); display:grid; grid-template-columns: repeat(3, 1fr); gap: clamp(12px, 2.0vw, 18px);}
    .coping .icon-card{min-height: clamp(140px, 18vh, 210px)}

    /* === TAKEAWAYS === */
    .bullets{margin-top: clamp(16px, 2.6vw, 26px); display:flex; flex-direction:column; gap: clamp(10px, 1.5vw, 14px);}
    .bullet{
      display:flex; gap: clamp(10px, 1.6vw, 14px);
      align-items:flex-start;
      padding: clamp(12px, 2.0vw, 16px);
      border-radius: clamp(14px, 1.8vw, 18px);
      border: 1px solid rgba(234,241,255,.14);
      background: rgba(255,255,255,.03);
    }
    .dot{
      width: clamp(10px, 1.3vw, 14px);
      height: clamp(10px, 1.3vw, 14px);
      border-radius: 99px;
      margin-top: clamp(4px, .6vw, 6px);
      background: var(--accent);
      box-shadow: 0 0 0 6px rgba(51,227,176,.10);
      flex: 0 0 auto;
    }
    .bullet p{margin:0; font-size: clamp(13px, 1.6vw, 18px); color: rgba(234,241,255,.82); line-height: 1.35;}

    @media (max-width: 980px){
      .barrow{grid-template-columns: 1fr;}
      .barvalue{text-align:left}
      .compare{grid-template-columns: 1fr;}
      .icon-grid{grid-template-columns: repeat(2, 1fr)}
      .coping{grid-template-columns: 1fr}
      .callouts{grid-template-columns: 1fr}
      .pair{grid-template-columns: 1fr}
    }
  </style>
</head>
<body>

  <!-- Slide 1: Title -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Mental Health • Global</div>
      <div class="page">01 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h1 class="h1 reveal" style="--d:.05s">The Global Burden of Mental Illness<span style="color:var(--accent)">.</span></h1>
        <p class="lede reveal" style="--d:.16s; margin-top: clamp(10px, 1.4vw, 16px)">Prevalence, impact, and the treatment gap — global data (2023).</p>
        <div class="pillrow reveal" style="--d:.28s">
          <div class="pill">Audience: public health policy analysts &amp; mental health program planners</div>
          <div class="pill">Source: Our World in Data (2023)</div>
          <div class="pill">Data: IHME, Global Burden of Disease (2025)</div>
        </div>
        <p class="small reveal" style="--d:.40s; margin-top: clamp(14px, 2.0vw, 22px)">Measure used in this deck: DALYs per 100,000 people (world, 2023).</p>
      </div>
    </div>
  </section>

  <!-- Slide 2: Prevalence scale -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Prevalence</div>
      <div class="page">02 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">Hundreds of Millions Affected</h2>
        <p class="lede reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">Lifetime risk of major depression is substantial.</p>

        <div class="callouts">
          <div class="callout reveal" style="--d:.24s">
            <div class="spark" aria-hidden="true"></div>
            <p class="big">1 in 3</p>
            <div class="label">Women</div>
            <div class="note">Will experience major depression in their lifetime.</div>
          </div>
          <div class="callout reveal" style="--d:.34s">
            <div class="spark" aria-hidden="true" style="opacity:.75"></div>
            <p class="big">1 in 5</p>
            <div class="label">Men</div>
            <div class="note">Will experience major depression in their lifetime.</div>
          </div>
        </div>

        <p class="small reveal" style="--d:.46s; margin-top: clamp(14px, 2.2vw, 22px)">
          Mental health conditions span from common disorders (depression, anxiety) to less common but severe conditions (schizophrenia, bipolar disorder).
        </p>
      </div>
    </div>
  </section>

  <!-- Slide 3: Burden by category (horizontal bar chart) -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Disease Burden (DALYs)</div>
      <div class="page">03 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">Depression and Anxiety Dominate</h2>
        <p class="small reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">World, 2023 • DALYs per 100,000 people (IHME GBD). Reference: figure_1.</p>

        <div class="chart-wrap reveal" style="--d:.22s">
          <div class="barlist" role="img" aria-label="Horizontal bar chart of DALYs per 100,000 people by mental illness category">
            <!-- Scale max = 694.6 (Depressive disorders) -->
            <div class="barrow">
              <div class="barlabel">Depressive disorders</div>
              <div class="bartrack"><div class="barfill" style="--pct:100"></div></div>
              <div class="barvalue">694.6</div>
            </div>
            <div class="barrow">
              <div class="barlabel">Anxiety disorders</div>
              <div class="bartrack"><div class="barfill" style="--pct:98.83"></div></div>
              <div class="barvalue">686.5</div>
            </div>
            <div class="barrow">
              <div class="barlabel">Schizophrenia</div>
              <div class="bartrack"><div class="barfill" style="--pct:30.26"></div></div>
              <div class="barvalue">210.2</div>
            </div>
            <div class="barrow">
              <div class="barlabel">Bipolar disorder</div>
              <div class="bartrack"><div class="barfill" style="--pct:13.62"></div></div>
              <div class="barvalue">94.6</div>
            </div>
            <div class="barrow">
              <div class="barlabel">Eating disorders</div>
              <div class="bartrack"><div class="barfill" style="--pct:6.84"></div></div>
              <div class="barvalue">47.5</div>
            </div>
          </div>
        </div>

        <p class="small reveal" style="--d:.34s; margin-top: clamp(12px, 2.0vw, 18px)">Depressive and anxiety disorders have nearly identical DALY rates (~695 and ~687).</p>
      </div>
    </div>
  </section>

  <!-- Slide 4: Depression vs anxiety parity -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Parity</div>
      <div class="page">04 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">Depression and Anxiety Carry Nearly Equal Disease Burden</h2>
        <p class="small reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">World, 2023 • DALYs per 100,000 people.</p>

        <div class="pair">
          <div class="paircard reveal" style="--d:.22s">
            <div class="pairname">Depressive disorders</div>
            <div class="pairnum">694.6</div>
            <div class="pairbar"><div style="--pct:100"></div></div>
          </div>
          <div class="paircard reveal" style="--d:.30s">
            <div class="pairname">Anxiety disorders</div>
            <div class="pairnum">686.5</div>
            <div class="pairbar"><div style="--pct:98.83"></div></div>
          </div>
        </div>

        <div class="parity reveal" style="--d:.40s">
          <span>Difference: <strong>8.1</strong> DALYs per 100,000</span>
          <span style="opacity:.7">(near-parity)</span>
        </div>

        <p class="small reveal" style="--d:.48s">Together, depressive and anxiety disorders dominate the mental health disease burden across these categories.</p>
      </div>
    </div>
  </section>

  <!-- Slide 5: Severe conditions -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Severe Conditions</div>
      <div class="page">05 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">Schizophrenia and Bipolar Disorder: Lower Prevalence but Severe Individual Impact</h2>
        <p class="small reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">World, 2023 • DALYs per 100,000 people.</p>

        <div class="compare">
          <div class="mini reveal" style="--d:.22s">
            <div style="display:flex; align-items:baseline; justify-content:space-between; gap:12px">
              <div style="font-weight:800; color: rgba(234,241,255,.86); font-size: clamp(14px, 1.55vw, 18px)">Schizophrenia</div>
              <div style="font-family:var(--mono); color: rgba(234,241,255,.72); font-size: clamp(12px, 1.35vw, 14px)">210.2</div>
            </div>
            <div class="stackbar" style="margin-top: clamp(10px, 1.6vw, 14px)"><div style="--pct:30.26"></div></div>

            <div class="stack" aria-hidden="true">
              <div style="display:flex; align-items:baseline; justify-content:space-between; gap:12px">
                <div style="font-weight:800; color: rgba(234,241,255,.86); font-size: clamp(14px, 1.55vw, 18px)">Bipolar disorder</div>
                <div style="font-family:var(--mono); color: rgba(234,241,255,.72); font-size: clamp(12px, 1.35vw, 14px)">94.6</div>
              </div>
              <div class="stackbar"><div style="--pct:13.62"></div></div>
            </div>

            <p class="small" style="margin-top: clamp(12px, 2.0vw, 18px)">Population-level DALYs are lower than depression/anxiety, but disability can be severe for individuals.</p>
          </div>

          <div class="mini reveal" style="--d:.30s">
            <div style="font-weight:800; color: rgba(234,241,255,.86); font-size: clamp(14px, 1.55vw, 18px)">Context (dominant categories)</div>
            <div class="stack" style="margin-top: clamp(10px, 1.6vw, 14px)">
              <div>
                <div style="display:flex; align-items:baseline; justify-content:space-between; gap:12px">
                  <div style="font-weight:700; color: rgba(234,241,255,.82)">Depressive disorders</div>
                  <div style="font-family:var(--mono); color: rgba(234,241,255,.72); font-size: clamp(12px, 1.35vw, 14px)">694.6</div>
                </div>
                <div class="stackbar" style="margin-top: clamp(8px, 1.2vw, 10px)"><div style="--pct:100"></div></div>
              </div>
              <div>
                <div style="display:flex; align-items:baseline; justify-content:space-between; gap:12px">
                  <div style="font-weight:700; color: rgba(234,241,255,.82)">Anxiety disorders</div>
                  <div style="font-family:var(--mono); color: rgba(234,241,255,.72); font-size: clamp(12px, 1.35vw, 14px)">686.5</div>
                </div>
                <div class="stackbar" style="margin-top: clamp(8px, 1.2vw, 10px)"><div style="--pct:98.83"></div></div>
              </div>
            </div>
            <p class="small" style="margin-top: clamp(12px, 2.0vw, 18px)">Keep specialist pathways for severe conditions while scaling interventions for common disorders.</p>
          </div>
        </div>

      </div>
    </div>
  </section>

  <!-- Slide 6: Treatment gap -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Treatment Gap</div>
      <div class="page">06 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">Treatment Is Available but Often Lacking or Poor Quality</h2>
        <p class="lede reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">Mental illnesses are treatable — yet many people do not receive adequate care.</p>

        <div class="icon-grid">
          <div class="icon-card reveal" style="--d:.22s">
            <div class="icon" aria-hidden="true">
              <!-- Stigma (mask) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M7 16c2.2 1.6 7.8 1.6 10 0" stroke="rgba(234,241,255,.9)" stroke-width="1.8" stroke-linecap="round"/>
                <path d="M8.2 11.2c.8-1.5 2.1-2.2 3.8-2.2s3 .7 3.8 2.2" stroke="rgba(234,241,255,.9)" stroke-width="1.8" stroke-linecap="round"/>
                <path d="M12 21a9 9 0 1 0-9-9" stroke="rgba(234,241,255,.55)" stroke-width="1.6" stroke-linecap="round"/>
              </svg>
            </div>
            <div class="icon-title">Stigma &amp; discomfort</div>
            <div class="icon-text">Many people feel uncomfortable sharing symptoms with healthcare professionals or people they know.</div>
          </div>

          <div class="icon-card reveal" style="--d:.30s">
            <div class="icon" aria-hidden="true" style="background:rgba(120,166,255,.14); border-color:rgba(120,166,255,.24)">
              <!-- Access (map pin) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M12 21s7-6 7-11a7 7 0 1 0-14 0c0 5 7 11 7 11Z" stroke="rgba(234,241,255,.9)" stroke-width="1.8"/>
                <path d="M12 10.2a2.2 2.2 0 1 0 0-4.4 2.2 2.2 0 0 0 0 4.4Z" fill="rgba(234,241,255,.65)"/>
              </svg>
            </div>
            <div class="icon-title">Access barriers</div>
            <div class="icon-text">Treatment is often lacking, especially in low- and middle-income countries.</div>
          </div>

          <div class="icon-card reveal" style="--d:.38s">
            <div class="icon" aria-hidden="true" style="background:rgba(255,94,168,.14); border-color:rgba(255,94,168,.24)">
              <!-- Quality (check) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M20 6 9 17l-5-5" stroke="rgba(234,241,255,.9)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
            </div>
            <div class="icon-title">Quality gaps</div>
            <div class="icon-text">Even where treatment exists, it may be of poor quality.</div>
          </div>

          <div class="icon-card reveal" style="--d:.46s">
            <div class="icon" aria-hidden="true">
              <!-- Underreporting (wave) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M4 15c3 0 3-6 6-6s3 6 6 6 3-6 4-6" stroke="rgba(234,241,255,.9)" stroke-width="1.8" stroke-linecap="round"/>
              </svg>
            </div>
            <div class="icon-title">Underreporting</div>
            <div class="icon-text">Discomfort with disclosure makes true prevalence difficult to estimate; burden may be higher than reported.</div>
          </div>
        </div>

        <p class="small reveal" style="--d:.54s; margin-top: clamp(14px, 2.2vw, 22px)">Implication for planners: improve help-seeking, access, and quality — while strengthening data collection.</p>
      </div>
    </div>
  </section>

  <!-- Slide 7: Coping strategies -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Coping &amp; Response</div>
      <div class="page">07 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
        <h2 class="h2 reveal" style="--d:.05s">How People Cope: From Medication to Faith to Family Conversations</h2>
        <p class="small reveal" style="--d:.14s; margin-top: clamp(8px, 1.2vw, 12px)">Global surveys show coping strategies vary widely across countries. Reference: figure_2.</p>

        <div class="coping">
          <div class="icon-card reveal" style="--d:.22s">
            <div class="icon" aria-hidden="true" style="background:rgba(120,166,255,.14); border-color:rgba(120,166,255,.24)">
              <!-- Medication (pill) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M10 14 16.5 7.5a4 4 0 1 1 5.7 5.7L15.7 19.7a4 4 0 1 1-5.7-5.7Z" stroke="rgba(234,241,255,.9)" stroke-width="1.8"/>
                <path d="M12.2 12.2 18 18" stroke="rgba(234,241,255,.55)" stroke-width="1.8" stroke-linecap="round"/>
              </svg>
            </div>
            <div class="icon-title">Prescribed medication</div>
            <div class="icon-text">Common in higher-income settings.</div>
          </div>

          <div class="icon-card reveal" style="--d:.30s">
            <div class="icon" aria-hidden="true">
              <!-- Faith (spark) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M12 2l1.6 6.2L20 10l-6.4 1.8L12 18l-1.6-6.2L4 10l6.4-1.8L12 2Z" stroke="rgba(234,241,255,.9)" stroke-width="1.8" stroke-linejoin="round"/>
              </svg>
            </div>
            <div class="icon-title">Religious / spiritual activities</div>
            <div class="icon-text">Prevalent in many regions worldwide.</div>
          </div>

          <div class="icon-card reveal" style="--d:.38s">
            <div class="icon" aria-hidden="true" style="background:rgba(255,94,168,.14); border-color:rgba(255,94,168,.24)">
              <!-- Social support (chat) -->
              <svg viewBox="0 0 24 24" fill="none">
                <path d="M20 15a4 4 0 0 1-4 4H9l-5 3V7a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v8Z" stroke="rgba(234,241,255,.9)" stroke-width="1.8" stroke-linejoin="round"/>
                <path d="M8 9h8M8 12h6" stroke="rgba(234,241,255,.55)" stroke-width="1.8" stroke-linecap="round"/>
              </svg>
            </div>
            <div class="icon-title">Talk to friends or family</div>
            <div class="icon-text">A widely reported coping mechanism.</div>
          </div>
        </div>

        <p class="small reveal" style="--d:.46s; margin-top: clamp(14px, 2.2vw, 22px)">Policy implication: interventions should be culturally sensitive — avoid one-size-fits-all approaches.</p>
      </div>
    </div>
  </section>

  <!-- Slide 8: Takeaways -->
  <section class="slide" data-slide>
    <div class="gridlines decorative" aria-hidden="true"></div>
    <div class="topbar">
      <div class="crumb">Policy Takeaways</div>
      <div class="page">08 / 08</div>
    </div>
    <div class="slide-content">
      <div class="card">
